REPLACE INTO `products` VALUES (1,1,1,'Heirloom Tomato Mix','A colorful mix of Cherokee Purple, Brandywine, and Green Zebra tomatoes. Vine-ripened, picked the morning of market.',5.50,40,'assets/images/products/heirloom-tomato-mix.webp','per lb',1,1,'2026-03-01 08:00:00'),(2,1,1,'Sweet Corn — Dozen','Peaches and Cream and Honey Select varieties. Harvested the morning of market. Sweetest corn north of the Twin Cities.',6.00,60,'assets/images/products/sweet-corn-dozen.webp','per dozen',1,1,'2026-03-01 08:00:00'),(3,1,1,'Organic Salad Mix','Baby arugula, red oak leaf, spinach, and nasturtium petals. Pre-washed, ready to dress. Certified organic.',4.50,50,'assets/images/products/organic-salad-mix.webp','per 5 oz bag',1,0,'2026-03-01 08:00:00'),(4,1,1,'Hardneck Garlic','Music and Chesnok Red varieties. Cured and ready to store. Grown without pesticides on this farm since 1994.',3.00,80,'assets/images/products/hardneck-garlic.webp','per bulb',1,0,'2026-03-01 08:00:00'),(5,1,1,'Butternut Squash','Large, dense butternut averaging 3-4 lbs each. Perfect for soups, roasting, and storing through winter.',4.00,35,'assets/images/products/butternut-squash.webp','each',1,0,'2026-03-01 08:00:00'),(6,2,2,'Cardamom Pulla Braid','Traditional Finnish sweet bread braided with butter, cardamom, and pearl sugar. Baked fresh Thursday morning. A family recipe since 1912.',9.00,20,'assets/images/products/cardamom-pulla-braid.webp','per loaf',1,1,'2026-03-01 09:00:00'),(7,2,2,'Sourdough Rye Loaf','Dense, tangy sourdough rye using a 40-year-old starter and locally milled dark rye flour. Keeps well for a full week.',8.50,18,'assets/images/products/sourdough-rye-loaf.webp','per loaf',1,0,'2026-03-01 09:00:00'),(8,2,2,'Wild Blueberry Scones — Half Dozen','Buttermilk scones loaded with wild Minnesota blueberries, finished with a light lemon glaze. Best eaten the same day.',7.00,25,'assets/images/products/wild-blueberry-scones.webp','per half dozen',1,1,'2026-03-01 09:00:00'),(9,2,2,'Rieska Flatbread','Traditional Finnish barley flatbread, soft and slightly dense. Best with butter and smoked fish. Baked in rounds.',5.00,30,'assets/images/products/rieska-flatbread.webp','per round',1,0,'2026-03-01 09:00:00'),(10,2,2,'Cast Iron Cinnamon Roll','Oversized cinnamon roll with cream cheese icing. Baked in cast iron for a caramelized bottom. Worth every penny.',4.50,24,'assets/images/products/cast-iron-cinnamon-roll.webp','each',1,0,'2026-03-01 09:00:00'),(11,3,3,'Aged Sharp Cheddar','Aged 9 months on the farm from our own Jersey milk. Rich, buttery depth you will not find in grocery store cheddar.',12.00,29,'assets/images/products/aged-sharp-cheddar.webp','per 8 oz block',1,1,'2026-03-01 10:00:00'),(12,3,3,'Fresh Chevre','Soft, tangy fresh goat cheese made twice weekly. Excellent on crackers, in salads, or spread on crusty bread.',8.00,20,'assets/images/products/fresh-chevre.webp','per 4 oz',1,0,'2026-03-01 10:00:00'),(13,3,3,'Whole Milk Yogurt','European-style whole milk yogurt, thick and creamy with a clean tang. Plain only — let the milk speak for itself.',6.50,25,'assets/images/products/whole-milk-yogurt.webp','per pint',1,0,'2026-03-01 10:00:00'),(14,3,3,'Farm Fresh Eggs','Eggs from our free-range hens. Fed on pasture, grain, and kitchen scraps. Deep orange yolks with a rich flavor.',5.00,40,'assets/images/products/farm-fresh-eggs.webp','per dozen',1,1,'2026-03-01 10:00:00'),(15,3,3,'Cultured Butter','Hand-churned cultured butter from our own cream. Available salted and unsalted. Rich, complex flavor.',9.00,22,'assets/images/products/cultured-butter.webp','per 8 oz',1,0,'2026-03-01 10:00:00'),(16,4,7,'Hand-Forged Bottle Opener','Forged from reclaimed Iron Range steel. Each one is slightly different. A functional piece of Range history.',28.00,15,'assets/images/products/hand-forged-bottle-opener.webp','each',1,1,'2026-03-01 11:00:00'),(17,4,7,'End-Grain Maple Cutting Board','10x14 inch end-grain maple board. Finished with food-safe walnut oil. Comes with a care card. Signed on the back.',65.00,8,'assets/images/products/end-grain-maple-cutting-board.webp','each',1,1,'2026-03-01 11:00:00'),(18,4,7,'Birch Log Candle Holder','Natural white birch log taper candle holder. Standard two-inch taper fits. Each piece is unique.',18.00,20,'assets/images/products/birch-log-candle-holder.webp','each',1,0,'2026-03-01 11:00:00'),(19,4,7,'Hand-Forged Leaf Trivet','Hand-forged iron trivet with a pressed aspen leaf design. Protects your table. Looks great on the wall too.',42.00,10,'assets/images/products/hand-forged-leaf-trivet.webp','each',1,0,'2026-03-01 11:00:00'),(20,5,4,'Berkshire Pork Chops','Bone-in center-cut chops from our heritage Berkshire pigs. Pasture and woodland-raised — the fat marbling is extraordinary.',14.00,25,'assets/images/products/berkshire-pork-chops.webp','per lb',1,1,'2026-03-01 08:30:00'),(21,5,4,'Maple Breakfast Sausage Links','Mild breakfast links from our own pork, seasoned with sage, thyme, and a little maple. No fillers, no nitrates.',10.00,30,'assets/images/products/maple-breakfast-sausage.webp','per lb',1,0,'2026-03-01 08:30:00'),(22,5,3,'Pastured Eggs — Large','Eggs from hens that follow the pigs through the pasture rotation. Deep orange yolks with rich flavor.',4.50,50,'assets/images/products/pastured-eggs-large.webp','per dozen',1,0,'2026-03-01 08:30:00'),(23,5,1,'Red New Potatoes','Small red new potatoes dug fresh this season. Thin skin, creamy texture. Roast whole with olive oil and rosemary.',4.00,45,'assets/images/products/red-new-potatoes.webp','per 2 lb bag',1,0,'2026-03-01 08:30:00'),(24,6,6,'Elderberry Tincture','Concentrated elderberry and echinacea tincture in alcohol base. Cold season staple. 2 oz dropper bottle. Shake before use.',22.00,20,'assets/images/products/elderberry-tincture.webp','per 2 oz bottle',1,1,'2026-03-01 12:00:00'),(25,6,6,'Northern Blend Herbal Tea','Warming blend of locally grown lemon balm, holy basil, rose hips, and dried blueberry. Caffeine-free. Loose leaf.',14.00,30,'assets/images/products/northern-blend-herbal-tea.webp','per 2 oz bag',1,1,'2026-03-01 12:00:00'),(26,6,6,'Lavender Facial Toner','Witch hazel, organic lavender hydrosol, and aloe vera. Calming and balancing for all skin types. No synthetic fragrance.',16.00,18,'assets/images/products/lavender-facial-toner.webp','per 4 oz bottle',1,0,'2026-03-01 12:00:00'),(27,6,6,'Organic Herb Seedling — 4 inch Pot','Choose from basil, lemon balm, holy basil, peppermint, thyme, or oregano. Certified organic starts from our greenhouse.',4.00,60,'assets/images/products/organic-herb-seedling.webp','each',1,0,'2026-03-01 12:00:00'),(28,6,6,'Calendula Healing Salve','Calendula-infused olive oil, beeswax, and vitamin E. For dry hands, chapped lips, and minor cuts.',12.00,25,'assets/images/products/calendula-healing-salve.webp','per 2 oz tin',1,0,'2026-03-01 12:00:00'),(29,7,4,'Grass-Fed Ground Beef','80/20 ground beef from our Angus-Hereford crosses. Dry-aged 14 days, ground fresh for market. Frozen in 1 lb vacuum packs.',9.00,40,'assets/images/products/grass-fed-ground-beef.webp','per lb',1,1,'2026-03-01 13:00:00'),(30,7,4,'NY Strip Steak','Boneless New York strip, cut 1.25 inches thick. Dry-aged 21 days. These sell out — arrive early.',22.00,16,'assets/images/products/ny-strip-steak.webp','per lb',1,1,'2026-03-01 13:00:00'),(31,7,4,'Lamb Shoulder Chops','Bone-in shoulder chops from our pasture-raised Katahdin lambs. Excellent braised slow or grilled over hardwood.',13.00,20,'assets/images/products/lamb-shoulder-chops.webp','per lb',1,0,'2026-03-01 13:00:00'),(32,7,4,'Grass-Fed Soup Bones','Marrow-rich knuckle and femur bones for bone broth. Two to three pounds per bag.',6.00,25,'assets/images/products/grass-fed-soup-bones.webp','per bag',1,0,'2026-03-01 13:00:00'),(33,8,7,'Stoneware Mug — 12 oz','Wheel-thrown stoneware in our signature pine bark glaze — deep forest green with brown iron spotting. Microwave and dishwasher safe.',38.00,12,'assets/images/products/stoneware-mug-12oz.webp','each',1,1,'2026-03-01 14:00:00'),(34,8,7,'Large Serving Bowl','Hand-built serving bowl in a natural ash glaze. Great for salads, pasta, or fruit. Each one is unique.',85.00,5,'assets/images/products/large-serving-bowl.webp','each',1,0,'2026-03-01 14:00:00'),(35,8,7,'Bud Vase Set — Pair','Matched pair of small wheel-thrown bud vases. Subtle glaze variation makes each set slightly different. A perfect gift.',48.00,8,'assets/images/products/bud-vase-set-pair.webp','per set',1,1,'2026-03-01 14:00:00'),(36,8,7,'Ceramic Soap Dish','Small hand-built soap dish with drainage ridges. Clean, simple design. Functional and good-looking.',22.00,18,'assets/images/products/ceramic-soap-dish.webp','each',1,0,'2026-03-01 14:00:00'),(37,9,5,'Raw Wildflower Honey','Unfiltered and unheated wildflower honey from boreal forest hives near Orr. Light to medium amber. Complex flavor.',12.00,35,'assets/images/products/raw-wildflower-honey.webp','per 8 oz jar',1,1,'2026-03-01 15:00:00'),(38,9,5,'Raw Clover Honey','Classic raw clover honey from agricultural meadow hives. Mild, sweet, perfect for everyday use. Never heat-processed.',10.00,40,'assets/images/products/raw-clover-honey.webp','per 8 oz jar',1,0,'2026-03-01 15:00:00'),(39,9,7,'Beeswax Pillar Candle','Pure beeswax pillar candle, 3x4 inches. Natural honey scent, clean long burn. No added fragrance or dye.',16.00,22,'assets/images/products/beeswax-pillar-candle.webp','each',1,1,'2026-03-01 15:00:00'),(40,9,7,'Beeswax Lip Balm','Beeswax and coconut oil lip balm in a twist tube. Unflavored or peppermint. No petroleum, no synthetic wax.',4.00,50,'assets/images/products/beeswax-lip-balm.webp','each',1,0,'2026-03-01 15:00:00'),(41,9,5,'Honey & Wild Berry Preserve','Local blueberries and wild raspberries preserved in raw honey. No added sugar, no pectin. Just fruit and honey.',11.00,18,'assets/images/products/honey-wild-berry-preserve.webp','per 6 oz jar',1,0,'2026-03-01 15:00:00'),(42,9,5,'Creamed Honey','Spun to a smooth, spreadable consistency. Stays soft at room temperature. Outstanding on toast, oatmeal, or straight off a spoon.',13.00,20,'assets/images/products/creamed-honey.webp','per 8 oz jar',1,0,'2026-03-01 15:00:00');
